import { useState, useMemo, useRef, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import ArrowBack from "@mui/icons-material/ArrowBack";
import CheckIcon from "@mui/icons-material/Check";
import SearchIcon from "@mui/icons-material/Search";
import CloseIcon from "@mui/icons-material/Close";
import PersonIcon from "@mui/icons-material/Person";
import BadgeIcon from "@mui/icons-material/Badge";
import ScheduleIcon from "@mui/icons-material/Schedule";
import KeyboardArrowDown from "@mui/icons-material/KeyboardArrowDown";
import EditIcon from "@mui/icons-material/Edit";
import GroupsIcon from "@mui/icons-material/Groups";
import { getProgrammes, getDelegates, getRoutes, getRoute, setDelegateRoutes } from "../../services/api";
import { joinProgramme, leaveProgramme, onAttendanceUpdated } from "../../services/socket";
import { timeAgo } from "../../services/utils";
import EmptyState from "../../components/shared/EmptyState";

const FILTERS = ["All", "Missing", "Present"];

export default function Directory() {
    const navigate = useNavigate();
    const [programmes, setProgrammes] = useState([]);
    const [programmeId, setProgrammeId] = useState(null);
    const [showPicker, setShowPicker] = useState(false);
    const [allDelegates, setAllDelegates] = useState([]);
    const [routes, setRoutes] = useState([]);

    const refreshData = () => {
        if (!programmeId) return;
        Promise.all([
            getDelegates(programmeId),
            getRoutes(programmeId),
        ])
            .then(([d, r]) => { setAllDelegates(d); setRoutes(r); })
            .catch(() => {});
    };

    useEffect(() => {
        const onSyncDone = () => refreshData();
        window.addEventListener('sync:done', onSyncDone);
        return () => window.removeEventListener('sync:done', onSyncDone);
    }, [programmeId]);
    const [search, setSearch] = useState("");
    const [filter, setFilter] = useState("All");
    const [selected, setSelected] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [noteText, setNoteText] = useState("");
    const [assigning, setAssigning] = useState(null);
    const [selectedRouteIds, setSelectedRouteIds] = useState([]);
    const sheetRef = useRef(null);

    useEffect(() => {
        getProgrammes()
            .then((list) => {
                setProgrammes(list);
                if (list.length > 0) setProgrammeId(list[0].id);
            })
            .catch((e) => setError(e.message));
    }, []);

    useEffect(() => {
        if (!programmeId) return;
        setLoading(true);
        Promise.all([
            getDelegates(programmeId),
            getRoutes(programmeId),
        ])
            .then(([delegates, routeList]) => {
                setAllDelegates(delegates);
                setRoutes(routeList);
            })
            .catch((e) => setError(e.message))
            .finally(() => setLoading(false));
    }, [programmeId]);

    useEffect(() => {
        if (!programmeId) return;
        joinProgramme(programmeId);
        return () => leaveProgramme(programmeId);
    }, [programmeId]);

    useEffect(() => {
        return onAttendanceUpdated((event) => {
            if (event.programmeId !== programmeId) return;
            setAllDelegates((prev) => prev.map((d) =>
                d.id === event.delegateId
                    ? { ...d, status: event.status, method: event.method, checkedInAt: event.checkedInAt }
                    : d
            ));
        });
    }, [programmeId]);

    const handleAssignRoute = async (delegateId) => {
        try {
            const validIds = selectedRouteIds.filter((id) => id);
            await setDelegateRoutes(programmeId, delegateId, validIds);
            setAssigning(null);
            setSelectedRouteIds([]);
            if (navigator.onLine) {
                const [delegates, routeList] = await Promise.all([
                    getDelegates(programmeId),
                    getRoutes(programmeId),
                ]);
                setAllDelegates(delegates);
                setRoutes(routeList);
            } else {
                const newRouteId = validIds[0] || null;
                const newRouteName = newRouteId ? (routes.find(r => r.id === newRouteId)?.name || null) : null;
                setAllDelegates(prev => prev.map(d =>
                    d.id === delegateId
                        ? { ...d, routeId: newRouteId, routeName: newRouteName, routeIds: validIds, routeNames: validIds.map(id => routes.find(r => r.id === id)?.name).filter(Boolean) }
                        : d
                ));
            }
        } catch (e) {
            // ignore
        }
    };

    const currentProgramme = programmes.find((p) => p.id === programmeId);

    const checkedMap = useMemo(() => {
        const map = {};
        allDelegates.forEach((d) => { map[d.id] = d.status === "present"; });
        return map;
    }, [allDelegates]);

    const delegates = useMemo(() => {
        let list = allDelegates;
        if (search.trim()) {
            const q = search.toLowerCase();
            list = list.filter((d) => d.name.toLowerCase().includes(q));
        }
        if (filter === "Missing") list = list.filter((d) => !checkedMap[d.id]);
        else if (filter === "Present") list = list.filter((d) => checkedMap[d.id]);
        return [...list].sort((a, b) => (checkedMap[a.id] === checkedMap[b.id] ? 0 : checkedMap[a.id] ? 1 : -1));
    }, [allDelegates, search, filter, checkedMap]);

    const missingCount = delegates.filter((d) => !checkedMap[d.id]).length;
    const handleBackdrop = (e) => { if (e.target === e.currentTarget) { setSelected(null); setNoteText(""); } };

    useEffect(() => {
        if (!selected) return;
        const onKey = (e) => { if (e.key === "Escape") { setSelected(null); setNoteText(""); } };
        window.addEventListener("keydown", onKey);
        return () => window.removeEventListener("keydown", onKey);
    }, [selected]);

    const isPresent = selected ? checkedMap[selected.id] : false;

    const header = (
        <header className="topbar">
            <div className="topbar-content">
                <button className="back-btn" onClick={() => navigate("/dashboard")} aria-label="Back to Dashboard">
                    <ArrowBack />
                </button>
                <h1 className="page-title">Directory</h1>
            </div>
            <div className="header-actions">
                <div className="relative">
                    <button
                        className="pill pill-neutral cursor-pointer"
                        onClick={() => setShowPicker((p) => !p)}
                    >
                        {currentProgramme?.name || "Select"}
                        <KeyboardArrowDown />
                    </button>
                    {showPicker && (
                        <div className="absolute top-full right-0 z-20 mt-1 min-w-[180px] overflow-hidden rounded-xl border border-edge bg-surface-2 p-1 shadow-2xl">
                            {programmes.map((p) => (
                                <button
                                    key={p.id}
                                    className={`row row-clickable w-full px-3 py-2 text-left text-xs font-medium ${
                                        p.id === programmeId ? "bg-accent/10 text-accent" : "text-muted"
                                    }`}
                                    onClick={() => { setProgrammeId(p.id); setShowPicker(false); }}
                                >
                                    {p.name}
                                </button>
                            ))}
                        </div>
                    )}
                </div>
                {missingCount > 0 && (
                    <span className="pill pill-warn">{missingCount} missing</span>
                )}
            </div>
        </header>
    );

    const loadingSkeleton = (
        <div className="space-y-3">
            {[0, 1, 2, 3, 4].map((i) => (
                <div key={i} className="card flex items-center gap-3 px-4 py-3">
                    <div className="skeleton avatar avatar-md" />
                    <div className="flex-1 space-y-2">
                        <div className="skeleton-text w-32" />
                        <div className="skeleton-text w-48" />
                    </div>
                </div>
            ))}
        </div>
    );

    if (loading && allDelegates.length === 0 && programmes.length === 0) {
        return (
            <main className="page">
                {header}
                <div className="px-4 pt-4">{loadingSkeleton}</div>
            </main>
        );
    }

    if (error && programmes.length === 0) {
        return (
            <main className="page">
                {header}
                <div className="px-4 pt-4">
                    <div className="banner banner-error">{error}</div>
                </div>
            </main>
        );
    }

    if (programmes.length === 0) {
        return (
            <main className="page">
                {header}
                <EmptyState icon={<GroupsIcon />} title="No programmes yet" desc="Create a programme to start tracking delegates." />
            </main>
        );
    }

    return (
        <main className="page">
            {header}

            <div className="px-4 pt-2">
                <div className="search-box">
                    <SearchIcon className="search-icon" />
                    <input
                        type="text"
                        placeholder="Search delegates..."
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        className="search-input"
                    />
                    {search && (
                        <button className="search-clear" onClick={() => setSearch("")} aria-label="Clear search">
                            <CloseIcon />
                        </button>
                    )}
                </div>
            </div>

            <div className="flex gap-2 px-4 pt-4">
                {FILTERS.map((f) => (
                    <button
                        key={f}
                        className={`filter-chip ${f === filter ? "filter-chip-active" : ""}`}
                        onClick={() => setFilter(f)}
                    >
                        {f}
                    </button>
                ))}
            </div>

            <div className="px-4 pt-4">
                {error && (
                    <div className="banner banner-error mb-3">{error}</div>
                )}
                {loading ? (
                    loadingSkeleton
                ) : delegates.length === 0 ? (
                    <EmptyState icon={<PersonIcon />} title="No delegates found" desc="No delegates match the current search or filter." />
                ) : (
                    <ul className="card card-divide">
                        {delegates.map((d) => {
                            const present = checkedMap[d.id];
                            return (
                                <li
                                    key={d.id}
                                    className="row row-clickable"
                                    onClick={() => { setSelected(d); setNoteText(""); }}
                                >
                                    <div className="row-left">
                                        <div className={`avatar avatar-md ${present ? "avatar-ok" : "avatar-warn"}`}>
                                            {d.name.charAt(0)}
                                        </div>
                                        <div className="row-text">
                                            <span className="row-title">{d.name}</span>
                                            <span className="row-meta">
                                                {d.routeName || "No route"} &middot; {present ? "Checked in" : "Not checked in"}
                                            </span>
                                        </div>
                                    </div>
                                    <div className="row-actions" onClick={(e) => e.stopPropagation()}>
                                        {assigning?.id === d.id ? (
                                            <div className="flex flex-col items-end gap-1">
                                                <div className="w-44">
                                                    <select
                                                        className="select text-xs"
                                                        value={selectedRouteIds[0] || ""}
                                                        onChange={(e) => setSelectedRouteIds(e.target.value ? [e.target.value] : [])}
                                                    >
                                                        <option value="">No route</option>
                                                        {routes.map((r) => (
                                                            <option key={r.id} value={r.id}>{r.name}</option>
                                                        ))}
                                                    </select>
                                                </div>
                                                <div className="flex gap-1">
                                                    <button className="btn btn-sm btn-primary" onClick={() => handleAssignRoute(d.id)}>Save</button>
                                                    <button className="btn btn-sm btn-ghost" onClick={() => setAssigning(null)}>Cancel</button>
                                                </div>
                                            </div>
                                        ) : (
                                            <button className="btn btn-sm btn-secondary" onClick={() => { setAssigning({ id: d.id }); setSelectedRouteIds(d.routeIds || []); }}>
                                                <EditIcon />
                                                Route
                                            </button>
                                        )}
                                    </div>
                                </li>
                            );
                        })}
                    </ul>
                )}
            </div>

            {selected && (
                <div className="sheet-backdrop" onClick={handleBackdrop}>
                    <div className="sheet" ref={sheetRef} role="dialog" aria-modal="true">
                        <div className="sheet-handle" />
                        <div className="sheet-header">
                            <div className="flex min-w-0 items-center gap-3">
                                <div className={`avatar avatar-lg ${isPresent ? "avatar-ok" : "avatar-warn"}`}>
                                    {selected.name.charAt(0)}
                                </div>
                                <div className="min-w-0">
                                    <h2 className="sheet-title">{selected.name}</h2>
                                    <p className="sheet-sub">{isPresent ? "Checked in" : "Not checked in"}</p>
                                </div>
                            </div>
                            <div className="flex shrink-0 items-center gap-1">
                                <span className={`pill ${isPresent ? "pill-ok" : "pill-warn"}`}>
                                    {isPresent ? "Present" : "Missing"}
                                </span>
                                <button className="sheet-close" onClick={() => { setSelected(null); setNoteText(""); }} aria-label="Close">
                                    <CloseIcon />
                                </button>
                            </div>
                        </div>
                        <div className="sheet-body">
                            <div className="card card-pad space-y-4">
                                <div className="flex items-center gap-3">
                                    <BadgeIcon className="text-muted" />
                                    <span className="meta flex-1">Badge</span>
                                    <span className="title">{selected.badge || "None"}</span>
                                </div>
                                <div className="flex items-center gap-3">
                                    <PersonIcon className="text-muted" />
                                    <span className="meta flex-1">Route</span>
                                    <span className="title">{selected.routeName || "None"}</span>
                                </div>
                                {isPresent && selected.method && (
                                    <div className="flex items-center gap-3">
                                        <ScheduleIcon className="text-muted" />
                                        <span className="meta flex-1">Checked in</span>
                                        <span className="title">{timeAgo(selected.checkedInAt)}</span>
                                    </div>
                                )}
                                {isPresent && selected.method && (
                                    <div className="flex items-center gap-3">
                                        <CheckIcon className="text-muted" />
                                        <span className="meta flex-1">Method</span>
                                        <span className="title">
                                            {selected.method === "auto" ? "Facial recognition" : "Manual check-in"}
                                        </span>
                                    </div>
                                )}
                                {!isPresent && selected.notes && (
                                    <div className="flex items-center gap-3">
                                        <span className="text-muted">!</span>
                                        <span className="meta flex-1">Note</span>
                                        <span className="title">{selected.notes}</span>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </main>
    );
}
